//! `cargo xtask diag-codes`: dump the diagnostic codes ts-r can report, with tsc's message
//! templates, as JSON. The website (`landing/`, Next.js) builds its error-code pages from it.
//!
//! Sources, all read from the checked-in tree (no upstream sync, no compiler crates linked):
//!
//! - the message catalogue `crates/ts_r_checker/src/diagnostics_generated.rs` (tsc's codes,
//!   categories and texts, generated by `cargo xtask codegen diagnostics`), for the texts;
//! - `crates/ts_r_diagnostics/src/messages.rs` and `crates/ts_r_binder/src/messages.rs`
//!   (`NAME = 1005 Error "..."` entries): lexer, parser and binder codes, kept when `NAME` is
//!   used in some crate's non-test source;
//! - `crates/ts_r_checker/src/*.rs`: every `dg::NAME_<code>` reference;
//! - `crates/ts_r_config/src/*.rs` and `crates/ts_r_check/src/*.rs`: numeric codes passed to
//!   the config diagnostic constructors, and `TS<code>` in printed messages.
//!
//! A code is listed when one of those references it. That means ts-r *can* report it; whether
//! a given input triggers it is for the site's example runner to show.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::path::Path;
use std::process::ExitCode;

use crate::args::Args;
use crate::util::{Result, read_to_string, root, walk_files, write_output};

const CATALOG: &str = "crates/ts_r_checker/src/diagnostics_generated.rs";

pub fn run(mut args: Args) -> Result<ExitCode> {
    let out = args.opt("out")?;
    args.finish()?;
    let root = root();
    let catalog = parse_catalog(&read_to_string(&root.join(CATALOG))?);
    if catalog.is_empty() {
        return Err(format!("{CATALOG}: no entries found").into());
    }

    // code -> emitting crates
    let mut emitted: BTreeMap<u32, BTreeSet<&'static str>> = BTreeMap::new();
    // Non-test sources of every crate, to keep only table entries something uses.
    let mut all = Vec::new();
    walk_files(&root.join("crates"), "rs", &mut all);
    let all: Vec<(std::path::PathBuf, String)> = all
        .into_iter()
        .filter(|p| !p.components().any(|c| c.as_os_str() == "tests") && !p.ends_with("tests.rs"))
        .map(|p| read_to_string(&p).map(|t| (p, t)))
        .collect::<Result<_>>()?;
    for (krate, file) in [
        (
            "ts_r_diagnostics",
            "crates/ts_r_diagnostics/src/messages.rs",
        ),
        ("ts_r_binder", "crates/ts_r_binder/src/messages.rs"),
    ] {
        let table = root.join(file);
        for (name, code) in macro_codes(&read_to_string(&table)?) {
            let used = all.iter().any(|(p, t)| *p != table && mentions(t, &name));
            if used {
                emitted.entry(code).or_default().insert(krate);
            }
        }
    }
    for text in rust_sources(&root.join("crates/ts_r_checker/src"))? {
        for code in dg_codes(&text) {
            emitted.entry(code).or_default().insert("ts_r_checker");
        }
    }
    for (krate, dir) in [
        ("ts_r_config", "crates/ts_r_config/src"),
        ("ts_r_check", "crates/ts_r_check/src"),
    ] {
        for text in rust_sources(&root.join(dir))? {
            for code in literal_codes(&text) {
                if catalog.contains_key(&code) {
                    emitted.entry(code).or_default().insert(krate);
                }
            }
        }
    }

    let mut json = String::new();
    json.push_str("{\n");
    let _ = writeln!(
        json,
        "  \"$comment\": \"Generated by `cargo xtask diag-codes` from {CATALOG} and the crates that report diagnostics. Do not edit by hand.\","
    );
    json.push_str("  \"codes\": [\n");
    let mut first = true;
    for (code, crates) in &emitted {
        // Codes ts-r owns (99xxx) are not in tsc's catalogue; take their text from the
        // ts_r_diagnostics table.
        let (category, message) = match catalog.get(code) {
            Some((c, m)) => (c.clone(), m.clone()),
            None => match own_message(&root, *code)? {
                Some(e) => e,
                None => continue,
            },
        };
        if !first {
            json.push_str(",\n");
        }
        first = false;
        let crates: Vec<String> = crates.iter().map(|c| format!("\"{c}\"")).collect();
        let _ = write!(
            json,
            "    {{ \"code\": {code}, \"category\": \"{category}\", \"message\": {}, \"crates\": [{}] }}",
            json_str(&message),
            crates.join(", ")
        );
    }
    json.push_str("\n  ]\n}\n");
    write_output(out.as_deref(), &json)?;
    eprintln!("diag-codes: {} codes", emitted.len());
    Ok(ExitCode::SUCCESS)
}

/// Every `.rs` file directly in `dir` except the generated catalogue, sorted.
fn rust_sources(dir: &Path) -> Result<Vec<String>> {
    let mut paths: Vec<_> = std::fs::read_dir(dir)?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| {
            p.extension().is_some_and(|e| e == "rs")
                && p.file_name()
                    .is_some_and(|n| n != "diagnostics_generated.rs")
        })
        .collect();
    paths.sort();
    paths.iter().map(|p| read_to_string(p)).collect()
}

/// `(code -> (category, message))` from the generated catalogue's `DiagnosticInfo` constants.
fn parse_catalog(text: &str) -> BTreeMap<u32, (String, String)> {
    let mut out = BTreeMap::new();
    let mut code = None;
    let mut category = None;
    for line in text.lines() {
        let t = line.trim();
        if let Some(rest) = t.strip_prefix("code: ") {
            code = rest.trim_end_matches(',').parse::<u32>().ok();
        } else if let Some(rest) = t.strip_prefix("category: Category::") {
            category = Some(rest.trim_end_matches(',').to_string());
        } else if let Some(rest) = t.strip_prefix("message: ")
            && let (Some(c), Some(cat)) = (code.take(), category.take())
            && let Some(msg) = rust_str(rest)
        {
            out.insert(c, (cat, msg));
        }
    }
    out
}

/// Decodes a Rust string literal at the start of `s` (`"..."`, simple escapes only).
fn rust_str(s: &str) -> Option<String> {
    let mut chars = s.strip_prefix('"')?.chars();
    let mut out = String::new();
    while let Some(c) = chars.next() {
        match c {
            '"' => return Some(out),
            '\\' => match chars.next()? {
                'n' => out.push('\n'),
                't' => out.push('\t'),
                'r' => out.push('\r'),
                '0' => out.push('\0'),
                'u' => {
                    let rest: String = chars.by_ref().take_while(|&c| c != '}').collect();
                    let hex = rest.trim_start_matches('{');
                    out.push(char::from_u32(u32::from_str_radix(hex, 16).ok()?)?);
                }
                other => out.push(other),
            },
            c => out.push(c),
        }
    }
    None
}

/// Whether `text` uses the identifier `name` outside line comments.
fn mentions(text: &str, name: &str) -> bool {
    text.lines().any(|line| {
        let code = line.split("//").next().unwrap_or("");
        code.match_indices(name).any(|(i, _)| {
            let before = code[..i].chars().next_back();
            let after = code[i + name.len()..].chars().next();
            let ident = |c: Option<char>| c.is_some_and(|c| c.is_ascii_alphanumeric() || c == '_');
            !ident(before) && !ident(after)
        })
    })
}

/// `(NAME, code)` from `NAME = 1005 Error "..."` lines of a `messages!` table.
fn macro_codes(text: &str) -> Vec<(String, u32)> {
    let mut out = Vec::new();
    for line in text.lines() {
        let t = line.trim();
        let Some((name, rest)) = t.split_once(" = ") else {
            continue;
        };
        if name.is_empty()
            || !name
                .bytes()
                .all(|b| b.is_ascii_uppercase() || b.is_ascii_digit() || b == b'_')
        {
            continue;
        }
        let mut parts = rest.splitn(3, ' ');
        if let (Some(num), Some(cat)) = (parts.next(), parts.next())
            && matches!(cat, "Error" | "Warning" | "Suggestion" | "Message")
            && let Ok(code) = num.parse()
        {
            out.push((name.to_string(), code));
        }
    }
    out
}

/// Codes from `dg::NAME_<code>` references outside comments.
fn dg_codes(text: &str) -> Vec<u32> {
    let mut out = Vec::new();
    for line in text.lines() {
        let code_part = line.split("//").next().unwrap_or("");
        let mut rest = code_part;
        while let Some(i) = rest.find("dg::") {
            rest = &rest[i + 4..];
            let ident: String = rest
                .chars()
                .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
                .collect();
            if let Some((_, digits)) = ident.rsplit_once('_')
                && let Ok(code) = digits.parse()
            {
                out.push(code);
            }
        }
    }
    out
}

/// Numeric codes in config/CLI sources: `TS<code>` inside string literals, and 4-5 digit
/// integer arguments followed by a comma (`ConfigDiagnostic::at(5024, ...)`, `c.key(id, 5102,
/// ...)`), outside comments and `#[cfg(test)]` modules. The caller keeps only catalogue codes.
fn literal_codes(text: &str) -> Vec<u32> {
    let mut out = Vec::new();
    for line in text.lines() {
        let t = line.trim_start();
        if t.starts_with("#[cfg(test)]") {
            break;
        }
        if t.starts_with("//") {
            continue;
        }
        let bytes = line.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            if !bytes[i].is_ascii_digit() {
                i += 1;
                continue;
            }
            let start = i;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            let digits = &line[start..i];
            let after_ts = start >= 2 && &line[start - 2..start] == "TS";
            let prev = if start > 0 { bytes[start - 1] } else { b' ' };
            let standalone = !(prev.is_ascii_alphanumeric() || prev == b'_' || prev == b'.');
            let arg = standalone && bytes.get(i).copied() == Some(b',');
            if (4..=5).contains(&digits.len())
                && (after_ts || arg)
                && let Ok(code) = digits.parse::<u32>()
                && code >= 1000
            {
                out.push(code);
            }
        }
    }
    out
}

/// Category and text of a ts-r-only code from `ts_r_diagnostics`' table.
fn own_message(root: &Path, code: u32) -> Result<Option<(String, String)>> {
    let text = read_to_string(&root.join("crates/ts_r_diagnostics/src/messages.rs"))?;
    let needle = format!(" = {code} ");
    for line in text.lines() {
        if let Some(i) = line.find(&needle) {
            let rest = &line[i + needle.len()..];
            if let Some((cat, lit)) = rest.split_once(' ')
                && let Some(msg) = rust_str(lit)
            {
                return Ok(Some((cat.to_string(), msg)));
            }
        }
    }
    Ok(None)
}

fn json_str(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| "\"\"".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn scanners() {
        assert_eq!(
            dg_codes("self.error(n, dg::CANNOT_FIND_NAME_0_2304, &[]); // dg::X_1"),
            vec![2304]
        );
        assert_eq!(
            macro_codes("    EXPECTED = 1005 Error \"'{0}' expected.\";"),
            vec![("EXPECTED".to_string(), 1005)]
        );
        assert!(mentions("x(messages::EXPECTED, s)", "EXPECTED"));
        assert!(!mentions(
            "x(messages::EXPECTED_X, s) // EXPECTED",
            "EXPECTED"
        ));
        assert_eq!(
            literal_codes("        5055,\n d.at(it.span, 5090, \"x\")"),
            vec![5055, 5090]
        );
        assert_eq!(
            literal_codes("println!(\"error TS5058: x\"); let a = [1, 2]; f(x1234, 0)"),
            vec![5058]
        );
        assert_eq!(
            rust_str(r#""a \"b\" \\ c","#).as_deref(),
            Some(r#"a "b" \ c"#)
        );
        let cat = parse_catalog(
            "pub const X_1002: DiagnosticInfo = DiagnosticInfo {\n    code: 1002,\n    category: Category::Error,\n    message: \"Unterminated string literal.\",\n",
        );
        assert_eq!(
            cat.get(&1002).map(|e| e.1.as_str()),
            Some("Unterminated string literal.")
        );
    }
}
